	assign {TX_P[i],TX_N[i]} = rx_phy_sel[i] ? {TX_Px,TX_Nx} : 2'b11 ; //根据接收信号 rx_phy_sel[i] 的选择，将数据分发到对应的正负端口 TX_P[i] 和 TX_N[i]。
